  if(RoomNumber==28&&_smoke){if(_polarityStage==0)PlaceSmokePlayerOnButton(_polarityGateA!);else if(_polarityStage==1&&_platform!.Progress>=.35f)PlaceSmokePlayerOnButton(_polarityGateB!);}
