  ForceVolume3D lowGravity=new(){Name="FinalLowGravity",Position=new Vector3(0,13,-194),CollisionLayer=0,CollisionMask=1,Profile=GD.Load<ForceVolumeProfile>("res://resources/force_volumes/low_gravity.tres")};lowGravity.AddChild(new CollisionShape3D{Shape=new BoxShape3D{Size=new Vector3(30,24,112)}});AddChild(lowGravity);RoomGeometry.AddLowGravityMotes(this,"FinalLowGravityMotes",lowGravity.Position,new Vector3(14,11,54),132);
  AddFinalFlightGate("FinalFlightGateOne",0,new Vector3(0,11.8f,-161));AddFinalFlightGate("FinalFlightGateTwo",1,new Vector3(0,14,-191));AddFinalFlightGate("FinalFlightGateThree",2,new Vector3(0,11.8f,-221));
  int cannonIndex=0;foreach(float z in Enumerable.Range(0,42).Select(index=>Mathf.Lerp(-148f,-238f,index/41f))){float routeY=z>=-161f?Mathf.Lerp(9f,11.8f,Mathf.Clamp((-z-148f)/13f,0,1)):z>=-191f?Mathf.Lerp(11.8f,13f,(-z-161f)/30f):z>=-221f?Mathf.Lerp(13f,11.8f,(-z-191f)/30f):Mathf.Lerp(11.8f,7f,Mathf.Clamp((-z-221f)/29f,0,1));float verticalShift=Mathf.PosMod(routeY-3.8f,3.2f);if(verticalShift>1.6f)verticalShift-=3.2f;foreach(float y in Enumerable.Range(0,10).Select(index=>index*3.2f))foreach(float side in new[]{-1f,1f}){cannonIndex++;InterferenceCannon3D cannon=new(){Name=$"InterferenceCannon{cannonIndex}",Position=new Vector3(side*9.5f,y+verticalShift,z),MuzzleOffset=new Vector3(-side*2.8f,2.2f,0),ProjectileVelocity=new Vector3(-side*21,0,0),InitialDelayTicks=10+(cannonIndex*7)%180,CadenceTicks=90+(cannonIndex*13)%120,ProjectileLifetimeTicks=58,PoolSize=2,EnableAudio=!_smoke&&cannonIndex%12==0,EnableWarningLight=cannonIndex%8==0,UseBatchedDenseVisuals=true};cannon.PlayerHit+=player=>{if(player==_p)_cannonHit=true;};AddChild(cannon);_interferenceCannons.Add(cannon);}}InterferenceCannon3D.AddDenseVisualBatch(this,_interferenceCannons);
