 private RouteCheckpoint3D CourseButton(string name,int index,Vector3 position,Vector3 size)=>new(){Name=name,CheckpointIndex=index,Position=position,TriggerSize=size,FrameTint=RoomGeometry.SequenceButtonFrameTint,FlatFloorMarker=true,RequireFloorContact=true,AutomaticPressEnabled=true,ShowFloorButtonIndicators=true};
 private Area3D CourseArea(string name,Vector3 position,Vector3 size){Area3D area=new(){Name=name,Position=position,CollisionLayer=0,CollisionMask=1,Monitoring=true,Monitorable=false};area.AddChild(new CollisionShape3D{Shape=new BoxShape3D{Size=size}});return area;}
 private void AddSurfaceStage(string name,Vector3 size,Vector3 position,string profilePath,Color color,string texturePath="res://assets/textures/rubber_chevrons.svg",Vector3 rotation=default){SurfaceProfile profile=GD.Load<SurfaceProfile>(profilePath);StandardMaterial3D material=RoomGeometry.CreateMaterial(texturePath,color,.18f,.58f,emissionEnabled:true,emission:color.Darkened(.62f));RoomGeometry.AddBox(this,name,size,position,rotation,string.Empty,Colors.White,0,profile.Friction,surfaceProfile:profile,materialOverride:material);}
 private void AddLaneRails(string prefix,float x,float z,float width,float length,Color color){foreach(float side in new[]{-1f,1f})RoomGeometry.AddWall(this,$"{prefix}Rail{side}",new Vector3(.34f,1.35f,length),new Vector3(x+side*(width*.5f+.18f),5.05f,z),Vector3.Zero,"res://assets/textures/brushed_metal.png",color,.42f,.64f);}
 private void AddFinalFlightGate(string name,int index,Vector3 position){FlightGate3D gate=new(){Name=name,Position=position,Radius=2.35f,MinimumExitSpeed=25,SpeedGain=0,SpeedMultiplier=1,MaximumExitSpeed=40,AxialBoostOnly=true,EnableAudio=!_smoke};gate.Passed+=player=>{if(player!=_p)return;if(index==_flightGateStage){_flightGateStage++;if(_flightGateStage==_flightGates.Count)_correctRail=true;}};AddChild(gate);_flightGates.Add(gate);}
 private bool FinalCannonsFillWalls()=>_interferenceCannons.Count==840&&_interferenceCannons.Select(cannon=>cannon.ScheduledFirstFireTick).Distinct().Count()>=100&&_interferenceCannons.All(cannon=>cannon.UseBatchedDenseVisuals)&&InterferenceCannon3D.HasDenseVisualBatch(this,840)&&_interferenceCannons.Min(cannon=>cannon.Position.Y)<=1.61f&&_interferenceCannons.Max(cannon=>cannon.Position.Y)>=27.19f&&_interferenceCannons.Min(cannon=>cannon.Position.Z)<=-237.99f&&_interferenceCannons.Max(cannon=>cannon.Position.Z)>=-148.01f;
 private void AddCaramelAbsorber(Vector3 size,Vector3 position){SurfaceProfile profile=GD.Load<SurfaceProfile>("res://resources/surfaces/absorbing.tres");ShaderMaterial material=(ShaderMaterial)GD.Load<ShaderMaterial>("res://resources/materials/sticky_caramel.tres").Duplicate();RoomGeometry.AddBox(this,"CaramelAbsorbingLanding",size,position,Vector3.Zero,string.Empty,Colors.White,0,profile.Friction,surfaceProfile:profile,materialOverride:material);}
private void AddCounterweight(Vector3 p){_counterweight=new Node3D{Name="Counterweight",Position=p};_counterStart=p;AddChild(_counterweight);RoomGeometry.AddVisualBox(_counterweight,"Mass",new Vector3(5,7,5),Vector3.Zero,Vector3.Zero,"res://assets/textures/copper_rivets.svg",new Color("6c5d48"),.45f,.58f);_counterweightCableTop=44.8f;float bottom=p.Y+3.5f;_counterweightCableBaseLength=_counterweightCableTop-bottom;_counterweightCable=RoomGeometry.AddVisualBox(this,"Cable",new Vector3(.22f,_counterweightCableBaseLength,.22f),new Vector3(p.X,(bottom+_counterweightCableTop)*.5f,p.Z),Vector3.Zero,"res://assets/textures/brushed_metal.png",new Color("2d3030"),.45f,.55f);StandardMaterial3D pulley=RoomGeometry.CreateMaterial("res://assets/textures/copper_rivets.svg",new Color("8d7451"),.45f,.55f);RoomGeometry.AddCylinder(this,"Pulley",new Vector3(p.X,45.5f,p.Z),new Vector3(Mathf.Pi/2,0,0),2.2f,.7f,pulley);}
private void UpdateCounterweightCable(){if(_counterweight is null||_counterweightCable is null)return;float bottom=_counterweight.Position.Y+3.5f;float length=Mathf.Max(.2f,_counterweightCableTop-bottom);_counterweightCable.Position=new Vector3(_counterweight.Position.X,(bottom+_counterweightCableTop)*.5f,_counterweight.Position.Z);_counterweightCable.Scale=new Vector3(1,length/_counterweightCableBaseLength,1);}
 private void BuildGoal(){Vector3 pos=RoomNumber switch{27=>new Vector3(8,5.35f,-62),28=>new Vector3(6.5f,25.35f,-49),29=>new Vector3(-75,8.35f,-25),30=>new Vector3(0,5.35f,-281),_=>new Vector3(0,5.35f,-48)};Area3D g=new(){Name="GoalCup",Position=pos,CollisionLayer=0,CollisionMask=1,Monitoring=true};g.AddChild(new CollisionShape3D{Shape=new CylinderShape3D{Radius=2.2f,Height=3}});g.BodyEntered+=body=>{if(body is PlayerBall&&Requirements()){if(RoomNumber==29&&!_railTouchedAfterStart)MarkAdvancementCondition("smooth-operator");if(RoomNumber==30&&_correctRail&&!_cannonHit)MarkAdvancementCondition("final-inspection");CompleteRoom();}};AddChild(g);Vector3? outward=RoomNumber switch{27=>Vector3.Right,29=>Vector3.Left,_=>null};ExitDoor3D door=RoomGeometry.AddGoalExitDoor(this,pos,outward);if((RoomNumber is 29 or 30)&&door.GetNodeOrNull<OmniLight3D>("DoorFillLight") is OmniLight3D light){light.LightColor=Colors.White;light.LightEnergy=.55f;}}
 private void RunHitSurvivalSmoke(){if(RoomNumber!=30){Fail("hit-survival smoke was requested outside Room 30");return;}_bankReleased=_pistonFired=_fired=_absorbed=_correctRail=_cannonHit=true;_flightGateStage=_flightGates.Count;GetNode<Area3D>("GoalCup").EmitSignal(Area3D.SignalName.BodyEntered,_p);if((!IsComplete&&!IsExitTraversalPending)||CompletedAdvancementIds.Contains("final-inspection")){Fail($"surviving a cannon hit did not complete normally or incorrectly awarded Final Inspection: complete={IsComplete||IsExitTraversalPending}, awarded={CompletedAdvancementIds.Contains("final-inspection")}");return;}GD.Print($"ROOM30_HIT_SURVIVAL_PASS: all {_interferenceCannons.Count} cannons remain optional hazards; a surviving hit denies Final Inspection but does not block completion.");Finish(0);}
 private void Fail(string m){GD.PushError($"ROOM{RoomNumber:00}_SOLUTION_FAIL: {m}");Finish(1);}private async void Finish(int c){if(_finish)return;_finish=true;_trace=null;await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);GetTree().Quit(c);}
